class Solution:
    def intersection(self, nums1: List[int], nums2: List[int]) -> List[int]:
        small, large = (nums1, nums2) if len(nums1) <= len(nums2) else (nums2, nums1)
        seen = set(small)
        result = []
        for x in large:
            if x in seen:
                result.append(x)
                seen.remove(x)
        result.sort()
        return result

